417: 	if err != nil {
418: 		return control.QueueView{}, fmt.Errorf("%w: %v", control.ErrBadInput, err)
419: 	}
420: 	p.state.Loop = *supervisor.New(project, q)
421: 	p.queuedAt = d.deps.Now()
422: 	if d.runningCount() < d.deps.Config.MaxParallel {
423: 		acts, berr := p.state.Loop.Begin(d.deps.Now())
424: 		if berr == nil {
